import{z as B,x as i,o as r,c as m,q as l,j as s,D as E,d as e,s as t,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"ROCm 的对照","description":"","frontmatter":{"title":"ROCm 的对照","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-rocm-comparison.md","filePath":"cs/gpu-rocm-comparison.md","lastUpdated":1791063341000}'),D={name:"cs/gpu-rocm-comparison.md"};function d(p,a,C,c,h,u){const o=i("Mermaid");return r(),m("div",null,[a[2]||(a[2]=l('<h1 id="rocm-的对照" tabindex="-1">ROCm 的对照 <a class="header-anchor" href="#rocm-的对照" aria-label="Permalink to &quot;ROCm 的对照&quot;">​</a></h1><div class="epigraph"><p>把 CUDA 的词汇逐条换成 ROCm 的对应物，剩下的不变量才是并行计算本身；翻译失败的地方，就是你原来依赖了厂商细节的地方。</p><footer>—— 据 AMD ROCm 与 HIP 文档整理</footer></div><p><a href="/cs/gpu-debugging">上一课</a>收了 NVIDIA 侧的工具链；本课换一家厂商做对照。前九课的词汇——CUDA、warp、smem、PTX——都是专名；AMD 的 ROCm 栈提供一套完整的平行词汇，大模型栏的<a href="/llm/ak-multi-backend">多后端移植</a>已经在内核工程里做过这种翻译。本课把翻译表本身当作课：哪些概念一一对应，哪些对应物尺寸不同、从而一切推论要重算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>迁移成本不均匀地分布在三层。语言层最浅：HIP 与 CUDA 几乎一一对应，<code>hipify</code> 工具能机械翻译大部分源码，同一份 HIP 甚至可选 NVIDIA 后端编译——它更像可移植层而不是另一套方言。<span class="marginnote">初学者容易以为「hipify 跑完、编译通过就算移植完了」：<code>cudaMalloc</code> 换成 <code>hipMalloc</code> 这类改名确实能机械完成，但那只占工作量的一小成——真正的大头在内核层重推 warp 假设、跑数值与性能验证，编译通过只是起跑线。</span>库层居中：rocBLAS、hipBLASLt 对 cuBLAS，MIOpen 对 cuDNN，接口平移，调优深度与覆盖面有差。内核层最深，也最容易被低估：所有按「warp 等于 32」写下的假设——shuffle 归约、butterfly 表、占用率账、bank 映射——要全部重推。缺的是一张判据明确的翻译表：哪条翻译是无损的，哪条翻译之后数字要换。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表逐行过。thread block 对 workgroup，<code>__syncthreads</code> 对 barrier，语义同名同义；shared memory 对 LDS（Local Data Share），端口与分账的思路同、参数不同。<span class="marginnote">LDS 就是 AMD 给 shared memory 起的名字：同样是每个 workgroup 一块的片上暂存区。可以把它想象成同一间储物间换了块门牌——储物规则（bank 分账）思路还在，但柜子数量和开门方式要重新查表，照抄 bank 账会踩坑。</span>warp 对 wavefront——这是最大的一处：CDNA（Instinct 卡）64 lane，RDNA 32 lane，今天的 MI300X 是 CDNA3，走 64。shuffle 对 bpermute / permute 一类指令，走 LDS 实现或专用交换，宽度与语义都与 <code>__shfl_sync</code> 不同，mask 合同另立。指令层：PTX 对 AMDGCN ISA，同样有中间表示到芯片指令的两级。寄存器文件多出一层：标量单元的 SGPR 管控制流与地址，向量单元的 VGPR 管数据——GCN/CDNA 把两条通路分开，wave 内分支粒度是整条 wave，与 <a href="/cs/gpu-simt">SIMT</a> 的共享 PC 同一家族。工具链平行物齐全：rocm-smi、rocprof、Omniperf 对 nvidia-smi 与 NCU，ROCgdb 对 cuda-gdb。</p>',7)),(r(),s(n,null,{default:E(()=>[t(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUDA%5B%22CUDA%20%E8%AF%8D%E6%B1%87%22%5D%20--%3E%20HIP%5B%22HIP%EF%BC%9A%E6%BA%90%E7%A0%81%E7%BA%A7%E5%B9%B3%E7%A7%BB%EF%BC%8C%E5%8F%AF%E7%BC%96%20NVIDIA%20%E5%90%8E%E7%AB%AF%22%5D%0A%20%20HIP%20--%3E%20W%5B%22warp%2032%20%E5%AF%B9%20wavefront%2064%EF%BC%88CDNA%EF%BC%89%2F%2032%EF%BC%88RDNA%EF%BC%89%22%5D%0A%20%20HIP%20--%3E%20S%5B%22smem%20%E5%AF%B9%20LDS%EF%BC%9Abank%20%E6%80%9D%E8%B7%AF%E5%90%8C%E3%80%81%E5%8F%82%E6%95%B0%E5%BC%82%22%5D%0A%20%20HIP%20--%3E%20SH%5B%22shuffle%20%E5%AF%B9%20bpermute%20%2F%20permute%EF%BC%9A%E5%AE%BD%E5%BA%A6%E4%B8%8E%E5%90%88%E5%90%8C%E5%8F%A6%E7%AB%8B%22%5D%0A%20%20W%20--%3E%20REDO%5B%22%E5%BD%92%E7%BA%A6%E6%AD%A5%E6%95%B0%205%20%E5%8F%98%206%EF%BC%8Cmask%20%E4%B8%8E%E5%8D%A0%E7%94%A8%E7%8E%87%E8%A1%A8%E9%87%8D%E6%8E%A8%22%5D%0A%20%20SH%20--%3E%20REDO%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,[e("wave64 为什么是一切的分水岭：第三课的 butterfly 归约步数从 \\(\\log_2 32 = 5\\) 变成 \\(\\log_2 64 = 6\\)，交换宽度、掩码约定、占用率的上限与下限全部联动——用 warp32 假设写的模板直译过去，轻则慢一半，重则后 32 个 lane 拿未定义值。这不只是 API 差异，是调度原子的尺寸变了，第一课「线程折成 warp」的折法随之改变。SGPR/VGPR 分离的推论也值得记：寄存器压力账要分两本，控制流的自燃依赖（分支条件、地址算术）走标量单元后，向量寄存器的预算可以留给数据——同一份核在两家上的占用率瓶颈常在不同科目上。"),A("span",{class:"marginnote"},"SGPR 与 VGPR 的分工可以想象成餐厅：SGPR 是贴在墙上的固定告示（菜价、桌号——全 wave 一致的控制流和地址，一份就够），VGPR 是每桌客人自己点的菜单（数据，每个 lane 一份）。告示不占菜单的钱，所以寄存器预算要分两本记，占用率账才能算对。")],-1)),(r(),s(n,null,{default:E(()=>[t(o,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5B%22warp32%20%E6%A8%A1%E6%9D%BF%EF%BC%9A%E5%BD%92%E7%BA%A6%20%2F%20mask%20%2F%20%E5%8D%A0%E7%94%A8%E7%8E%87%E8%A1%A8%22%5D%20--%3E%7C%22%E7%9B%B4%E8%AF%91%E5%88%B0%20wave64%22%7C%20X%5B%22%E4%B8%89%E6%9C%AC%E8%B4%A6%E5%90%8C%E6%97%B6%E5%87%BA%E9%94%99%22%5D%0A%20%20X%20--%3E%20A%5B%22%E5%BD%92%E7%BA%A6%E6%AD%A5%E6%95%B0%205%20%E5%8F%98%206%EF%BC%9A%E4%BA%A4%E6%8D%A2%E5%AE%BD%E5%BA%A6%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20X%20--%3E%20B%5B%22mask%20%E6%8C%89%2032%20%E5%86%99%EF%BC%9A%E5%90%8E%2032%20%E4%B8%AA%20lane%20%E6%9C%AA%E5%AE%9A%E4%B9%89%22%5D%0A%20%20X%20--%3E%20C%5B%22%E5%8D%A0%E7%94%A8%E7%8E%87%E8%A1%A8%E7%85%A7%E6%8A%84%EF%BC%9A%E5%AF%84%E5%AD%98%E5%99%A8%E9%A2%84%E7%AE%97%E5%85%A8%E9%94%99%22%5D%0A%20%20S%5B%22SGPR%EF%BC%9A%E5%88%86%E6%94%AF%E6%9D%A1%E4%BB%B6%E4%B8%8E%E5%9C%B0%E5%9D%80%22%5D%20--%3E%7C%22%E5%8F%A6%E7%AB%8B%E4%B8%80%E6%9C%AC%E9%A2%84%E7%AE%97%22%7C%20V%5B%22VGPR%EF%BC%9A%E6%95%B0%E6%8D%AE%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20V%20--%3E%20D%5B%22%E5%8D%A0%E7%94%A8%E7%8E%87%E7%93%B6%E9%A2%88%E7%A7%91%E7%9B%AE%E8%B7%A8%E5%8E%82%E5%95%86%E4%B8%8D%E5%90%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>对照的真正收益在方法论检验：本课程九笔账——资源检查、层次价格、warp 通道、bank 序、碎片合同、分层库、计数器、竞态工具——在 ROCm 上全部有对应物，只有参数换。这印证了收束课要立的论点：账本结构是本质，账本数字是专名。移植的验收也照旧：先跑竞态与越界检查，再对数值，最后才比性能（<a href="/llm/ak-benchmark-methodology">基准方法论</a>的规矩在两家同样适用）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做性能裁决：两家每代互有胜负，数字随驱动与形状漂移，引用谁的基准都要带日期与版本。Intel 的 oneAPI 与 SYCL 是第三套词汇，本课不展开；具体指令编码归各家 ISA 手册（CDNA 系列的 ISA 参考是公开的）。HIP 的覆盖也有边界：最新的图形与视频栈、部分专有库没有对等物——翻译表上「查无此行」的地方，就是方案选型的风险位，要在迁移前标注而不是迁移中撞上。</p><p><span class="marginnote">一个典型移植坑：<code>__shfl_xor_sync(..., 32)</code> 的宽度常量直译后在 wave64 上只覆盖半个 wave，其余 lane 的返回值未定义——编译器不报错、结果「大体对」。移植后的第一件事是跑 sanitizer 类检查，第二件事才是看数值。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>迁移成本分三层：HIP 源码平移最浅，库接口居中，内核层的 warp 假设最深。</li><li>wavefront 尺寸是分水岭：CDNA 64、RDNA 32；归约步数、mask、占用率表全部联动重推。</li><li>SGPR/VGPR 分离让寄存器压力分两本账，占用率瓶颈科目可能与 NVIDIA 不同。</li><li>翻译表「查无此行」处是选型风险位，迁移前标注。</li><li>账本结构跨厂商不变、参数是专名——这是本课程方法可移植性的检验。</li><li>出处：AMD ROCm 与 HIP 文档；CDNA 系列 ISA 参考手册。</li></ul>',6))])}const F=B(D,[["render",d]]);export{P as __pageData,F as default};
